        graph,
        tags: OnceCell::new(),
        git: OnceCell::new(),
        runner: &runner,
        manifest_cache: Default::default(),
        identity: callisto_graph::IdentityIndex::default(),
    };

    let plan = plan_publish(&ws, &PublishOptions::default()).expect("plan_publish must succeed");
    let release = plan
        .releases
